acceptance.command:
python3 -c 'import os,pathlib,subprocess
base=pathlib.Path(os.environ["BASE_TREE"]).resolve()
scripts=["e2e/console-setup.test.sh","e2e/runtime-settings.test.sh","e2e/incident-card.test.sh","e2e/snippet.test.sh"]
outputs={}
for label,tree in [("base",base),("branch",pathlib.Path.cwd())]:
    for s in scripts:
        r=subprocess.run(["bash",s],cwd=tree,text=True,capture_output=True)
        print(label,s,r.stdout,end="",flush=True)
        assert r.returncode==0,(label,s,r.returncode)
        outputs[label,s]=r.stdout
for s in scripts[:2]:
    assert outputs["base",s]==outputs["branch",s],s+" stdout changed"
'
